#include <stdio.h>
#include <string.h>

int main(void) {
    char word[101], best[101] = "";
    size_t best_length = 0;
    while (scanf("%100s", word) == 1) {
        size_t length = strlen(word);
        if (length > best_length) {
            best_length = length;
            strcpy(best, word);
        }
    }
    printf("%s %zu\n", best, best_length);
    return 0;
}

