#include <stdio.h>
#include <string.h>

int main(void) {
    char text[1002], pattern[101];
    if (fgets(text, sizeof(text), stdin) == NULL) {
        return 0;
    }
    scanf("%100s", pattern);
    int count = 0;
    char *p = strstr(text, pattern);
    while (p != NULL) {
        count++;
        p = strstr(p + 1, pattern);
    }
    printf("%d\n", count);
    return 0;
}

