#include <stdio.h>
#include <string.h>

void swap_words(char a[], char b[]) {
    char tmp[51];
    strcpy(tmp, a);
    strcpy(a, b);
    strcpy(b, tmp);
}

int main(void) {
    char a[51], b[51], c[51];
    scanf("%50s %50s %50s", a, b, c);
    if (strcmp(a, b) > 0) {
        swap_words(a, b);
    }
    if (strcmp(b, c) > 0) {
        swap_words(b, c);
    }
    if (strcmp(a, b) > 0) {
        swap_words(a, b);
    }
    printf("%s\n%s\n%s\n", a, b, c);
    return 0;
}

